GLOSSARY = {
    "prompt": ("Prompt", "The instruction you give Claude. It can include the task, background, source material and how you want the answer laid out."),
    "hallucination": ("Hallucination", "When an AI model states something that sounds right but has no basis in the material it was given or in fact. Fluent wording is not evidence."),
    "objective": ("Objective", "The piece of work you want done, stated as a deliverable. 'Draft a status update' is an objective. 'Patching' is only a topic."),
    "context": ("Context", "Background that gives the task meaning: the project, the environment, what happened before. Also used for everything Claude can see in the current conversation."),
    "authoritative": ("Authoritative input", "The material you tell Claude to treat as the source of truth for this task. It is authoritative because your prompt says so."),
    "audience": ("Audience", "The people who will read the result. Their knowledge and needs decide the vocabulary, level of detail and tone."),
    "constraint": ("Constraint", "A boundary on the answer: what to leave out, what must not be claimed, which terms to use, how to treat missing information."),
    "format": ("Output format", "The shape of the answer: headings, a table, bullet points, a length limit. It says how to lay facts out. It does not supply the facts."),
    "evidence-boundary": ("Evidence boundary", "The line between what the supplied material supports and everything else. A good prompt tells Claude to stay inside it and say so when it reaches the edge."),
    "observable": ("Observable requirement", "A requirement a reviewer can check by looking: 'three headed paragraphs, under 150 words'. The opposite is a vague quality word like 'polished'."),
    "root-cause": ("Root cause", "The underlying reason a fault happened. It should only be stated once evidence supports it. Until then it is a hypothesis."),
    "hypothesis": ("Hypothesis", "A possible explanation that has not been proven yet. Keep it labelled as one until a check confirms or rules it out."),
    "diagnostic-loop": ("Diagnostic loop", "A troubleshooting routine: describe the fault, have Claude write one script that collects evidence, feed the output back, and only then reason about the cause. Repeat until the evidence proves it."),
    "decomposition": ("Decomposition", "Splitting a large job into smaller stages, each with its own input and its own checkable result."),
    "one-shot": ("One-shot prompt", "A single prompt that asks for the whole finished result in one go."),
    "intermediate": ("Intermediate deliverable", "A result produced part-way through a job, such as an extracted list of facts, that can be checked before later stages rely on it."),
    "inventory": ("Input inventory", "A list of everything the job should cover and every source it should draw on, written before any analysis starts."),
    "completeness-check": ("Completeness check", "Comparing what was actually extracted against the inventory, to catch anything that was skipped."),
    "human-gate": ("Human gate", "A stopping point where a person checks the work so far and decides whether Claude should carry on. Also called a checkpoint."),
    "dependency": ("Dependency", "Something that has to be finished and correct before the next thing can be trusted. Facts before analysis, analysis before recommendations."),
    "iteration": ("Iteration", "Improving a result through repeated rounds: get a draft, inspect it, name the main defect, revise the instruction, compare."),
    "defect": ("Defect", "The specific thing wrong with a draft. Naming its type (missing content, wrong tone, unsupported claim and so on) tells you which fix to use."),
    "knowledge-gap": ("Knowledge gap", "The answer is not in the material Claude was given. No amount of rewording the prompt fixes this. Someone has to supply the fact."),
    "rubric": ("Rubric", "A short list of criteria a draft must meet, written so each one can be ticked or crossed."),
    "follow-up": ("Follow-up prompt", "A new instruction in the same conversation that builds on what is already there, instead of starting again."),
    "context-drift": ("Context drift", "When a long conversation fills up with old drafts and replaced instructions, and Claude starts mixing outdated material back into new answers."),
    "analysis": ("Analysis", "Using evidence you already have to reach a decision: comparing options against stated criteria."),
    "research": ("Research", "Finding evidence and showing where each piece came from, including what could not be found."),
    "drafting": ("Drafting", "Turning agreed facts and a chosen direction into a piece of writing for a particular reader."),
    "brainstorming": ("Brainstorming", "Producing a wide spread of possible approaches before anyone judges them."),
    "chaining": ("Prompt chaining", "Running several prompts in order, where each one uses the checked result of the one before."),
    "recency": ("Recency", "How recent a source has to be to count. A research prompt should say so, for example 'published in the last 12 months'."),
    "citation": ("Citation", "A pointer from a statement to the source that supports it, so a reviewer can trace it."),
    "assumption": ("Assumption", "Something treated as true for the sake of the work without being proven. Good analysis lists assumptions separately from findings."),
    "change-board": ("Change board", "The group that approves changes to live systems before they are made. Often called CAB, the change advisory board."),
    "ccao-f": ("CCAO-F", "Claude Certified Associate, Foundations. Anthropic's entry-level certification exam on using Claude well for everyday work."),
}
